function MemberCard({ member, expanded, onToggle }: any) {
  return (
    <Pressable
      style={({ pressed }) => [styles.memberCard, { opacity: pressed ? 0.9 : 1 }]}
      onPress={() => {
        onToggle();
        Haptics.selectionAsync();
      }}
    >
      <View style={[styles.avatarCircle, { backgroundColor: member.color + "22", borderColor: member.color + "44" }]}>
        <Ionicons name={member.icon as any} size={32} color={member.color} />
      </View>
      <View style={{ flex: 1 }}>
        <View style={styles.memberTop}>
          <Text style={styles.memberName}>{member.name}</Text>
          <View style={[styles.badge, { backgroundColor: member.color + "22", borderColor: member.color + "44" }]}>
            <Text style={[styles.badgeText, { color: member.color }]}>{member.badge}</Text>
          </View>
        </View>
        <Text style={styles.memberRole}>{member.role}</Text>
        <View style={styles.memberMeta}>
          <Text style={styles.affiliateId}>{member.affiliateId}</Text>
          <View style={styles.dot} />
          {member.totalTeam > 0 && (
            <Text style={styles.teamCount}>{member.totalTeam} team members</Text>
          )}
        </View>
      </View>
      <Ionicons
        name={expanded ? "chevron-up" : "chevron-down"}
        size={16}
        color={C.TEXT_SECONDARY}
      />
    </Pressable>
  );
}

function MemberExpanded({ member }: any) {
  const callPhone = () => Linking.openURL(`tel:${member.phone}`);
  const sendEmail = () => Linking.openURL(`mailto:${member.email}`);

  return (
    <View style={styles.expandedCard}>
      <Text style={styles.bio}>{member.bio}</Text>
      <View style={styles.contactRow}>
        <Pressable
          style={({ pressed }) => [styles.contactBtn, { opacity: pressed ? 0.8 : 1 }]}
          onPress={callPhone}
        >
          <Ionicons name="call" size={18} color={C.SUCCESS} />
          <Text style={styles.contactText}>{member.phone}</Text>
        </Pressable>
        <Pressable
          style={({ pressed }) => [styles.contactBtn, { opacity: pressed ? 0.8 : 1 }]}
          onPress={sendEmail}
        >
          <Ionicons name="mail" size={18} color={C.BLUE} />
          <Text style={styles.contactText}>{member.email}</Text>
        </Pressable>
      </View>
    </View>
  );
}

export default function TeamScreen() {
  const insets = useSafeAreaInsets();
  const [search, setSearch] = useState("");
  const [expanded, setExpanded] = useState<string | null>(null);

  const topPad = insets.top + (Platform.OS === "web" ? 67 : 0);

  const allMembers = [CEO, ...HODS];
  const filtered = allMembers.filter(
    (m) =>
      m.name.toLowerCase().includes(search.toLowerCase()) ||
      m.role.toLowerCase().includes(search.toLowerCase()) ||
      m.department.toLowerCase().includes(search.toLowerCase())
  );

  const toggle = (id: string) => setExpanded(expanded === id ? null : id);

  return (
    <View style={styles.screen}>
      <ScrollView
        contentContainerStyle={{ paddingBottom: 120 }}
        showsVerticalScrollIndicator={false}
        contentInsetAdjustmentBehavior="automatic"
      >
        <LinearGradient
          colors={[C.NAVY, "#101630"]}
          style={[styles.header, { paddingTop: topPad + 16 }]}
        >
          <Text style={styles.headerTitle}>Leadership</Text>
          <View style={styles.searchBar}>
            <Ionicons name="search" size={18} color={C.TEXT_SECONDARY} />
            <TextInput
              style={styles.searchInput}
              placeholder="Search members..."
              placeholderTextColor={C.TEXT_SECONDARY}
              value={search}
              onChangeText={setSearch}
            />
            {search.length > 0 && (
              <Pressable onPress={() => setSearch("")}>
                <Ionicons name="close-circle" size={18} color={C.TEXT_SECONDARY} />
              </Pressable>
            )}
          </View>
        </LinearGradient>

        <View style={styles.content}>
          {filtered.map((member) => (
            <View key={member.id}>
              {member.id === "ceo" && (
                <View style={styles.section}>
                  <View style={styles.sectionHeader}>
                    <MaterialCommunityIcons name="crown" size={16} color={C.GOLD} />
                    <Text style={styles.sectionTitle}>Chief Executive</Text>
                  </View>
                </View>
              )}
              {member.id === "h1" && (
                <View style={styles.section}>
                  <View style={styles.sectionHeader}>
                    <Ionicons name="people" size={16} color={C.BLUE} />
                    <Text style={styles.sectionTitle}>Heads of Department</Text>
                  </View>
                </View>
              )}
              <MemberCard
                member={member}
                expanded={expanded === member.id}
                onToggle={() => toggle(member.id)}
              />
              {expanded === member.id && <MemberExpanded member={member} />}
            </View>
          ))}

          {filtered.length === 0 && (
            <View style={styles.empty}>
              <Ionicons name="people-outline" size={48} color={C.TEXT_SECONDARY} />
              <Text style={styles.emptyText}>No members found</Text>
            </View>
          )}

          <View style={styles.socialSection}>
            <Text style={styles.socialTitle}>Follow Proud Pakistani Company</Text>
            <View style={styles.socialGrid}>
              {SOCIAL_LINKS.map((s) => (
                <Pressable
                  key={s.label}
                  style={({ pressed }) => [
                    styles.socialBtn,
                    { borderColor: s.color + "44", opacity: pressed ? 0.8 : 1 },
                  ]}
                  onPress={() => {
                    Haptics.selectionAsync();
                    Linking.openURL(s.url);
                  }}
                >
                  <Ionicons name={s.icon as any} size={22} color={s.color} />
                  <Text style={[styles.socialLabel, { color: s.color }]}>{s.label}</Text>
                </Pressable>
              ))}
            </View>
          </View>
        </View>
      </ScrollView>
    </View>
  );
}

