import React, { useState } from "react";
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  Pressable,
  Platform,
  TextInput,
  Alert,
  Modal,
  Image,
  Linking,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { LinearGradient } from "expo-linear-gradient";
import { Ionicons, MaterialCommunityIcons } from "@expo/vector-icons";
import * as Haptics from "expo-haptics";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { useAuth } from "@/context/auth";
import C, { BRAND } from "@/constants/colors";

type ModalType = "leave" | "complaint" | null;

const LEAVE_TYPES = ["Sick Leave", "Casual Leave", "Emergency Leave", "Annual Leave"];

function formatPKR(n: number) {
  if (n >= 100000) return `₨ ${(n / 100000).toFixed(1)}L`;
  if (n >= 1000) return `₨ ${(n / 1000).toFixed(0)}K`;
  return `₨ ${n}`;
}

export default function ProfileScreen() {
  const insets = useSafeAreaInsets();
  const { user, logout } = useAuth();
  const [modal, setModal] = useState<ModalType>(null);

  const [leaveType, setLeaveType] = useState(LEAVE_TYPES[0]);
  const [leaveReason, setLeaveReason] = useState("");
  const [leaveDate, setLeaveDate] = useState("");
  const [leaveLoading, setLeaveLoading] = useState(false);

  const [complaint, setComplaint] = useState("");
  const [complaintLoading, setComplaintLoading] = useState(false);

  // --- NEW STATE FOR PROFILE PICTURE ---
  const [profileImage, setProfileImage] = useState<string | null>(null);

  const topPad = insets.top + (Platform.OS === "web" ? 67 : 0);

  // --- NEW HANDLER FOR PROFILE PICTURE UPLOAD ---
  const handleImageUpload = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    Alert.alert(
      "Update Profile Picture",
      "Would you like to open camera or gallery?",
      [
        { text: "Cancel", style: "cancel" },
        { text: "Gallery", onPress: () => Alert.alert("Gallery", "Gallery picker will open here.") },
        { text: "Camera", onPress: () => Alert.alert("Camera", "Camera will open here.") }
      ]
    );
  };

  const openZoomMeeting = () => {
    Haptics.selectionAsync();
    // Aap yahan apna asal Zoom link daal sakte hain
    Linking.openURL("https://zoom.us/join");
  };

  const submitLeave = async () => {
    if (!leaveReason.trim() || !leaveDate.trim()) {
      Alert.alert("Missing Info", "Please fill in all fields.");
      return;
    }
    setLeaveLoading(true);
    await Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
    const existing = JSON.parse((await AsyncStorage.getItem("@leaves")) ?? "[]");
    const newLeave = {
      id: Date.now().toString(),
      type: leaveType,
      reason: leaveReason,
      date: leaveDate,
      status: "Pending",
      submittedAt: new Date().toISOString(),
    };
    await AsyncStorage.setItem("@leaves", JSON.stringify([...existing, newLeave]));
    setLeaveLoading(false);
    setLeaveReason("");
    setLeaveDate("");
    setModal(null);
    Alert.alert("Leave Submitted", "Your leave request has been submitted for approval.");
  };

  const submitComplaint = async () => {
    if (!complaint.trim()) {
      Alert.alert("Empty Complaint", "Please describe your complaint.");
      return;
    }
    setComplaintLoading(true);
    await Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
    const existing = JSON.parse((await AsyncStorage.getItem("@complaints")) ?? "[]");
    const newComplaint = {
      id: Date.now().toString(),
      text: complaint,
      status: "Under Review",
      submittedAt: new Date().toISOString(),
    };
    await AsyncStorage.setItem("@complaints", JSON.stringify([...existing, newComplaint]));
    setComplaintLoading(false);
    setComplaint("");
    setModal(null);
    Alert.alert("Complaint Filed", "Your complaint has been submitted and will be reviewed.");
  };

  const confirmLogout = () => {
    Alert.alert("Sign Out", "Are you sure you want to sign out?", [
      { text: "Cancel", style: "cancel" },
      {
        text: "Sign Out",
        style: "destructive",
        onPress: () => {
          Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
          logout();
        },
      },
    ]);
  };

  return (
    <View style={styles.screen}>
      <ScrollView
        contentContainerStyle={{ paddingBottom: 120 }}
        showsVerticalScrollIndicator={false}
        contentInsetAdjustmentBehavior="automatic"
      >
        <LinearGradient
          colors={[C.NAVY, "#101630"]}
          style={[styles.header, { paddingTop: topPad + 16 }]}
        >
          <View style={styles.avatarWrap}>
            <View style={styles.avatar}>
              {profileImage ? (
                <Image source={{ uri: profileImage }} style={{ width: 88, height: 88, borderRadius: 44 }} />
              ) : (
                <Ionicons name="person" size={44} color={C.GOLD} />
              )}
            </View>
            {user?.role === "hod" && (
              <View style={styles.roleBadge}>
                <MaterialCommunityIcons name="crown" size={12} color={C.NAVY} />
                <Text style={styles.roleBadgeText}>HOD</Text>
              </View>
            )}
            {/* --- NEW UPLOAD PICTURE BUTTON --- */}
            <Pressable style={styles.uploadIcon} onPress={handleImageUpload}>
              <Ionicons name="camera" size={16} color="#FFF" />
            </Pressable>
          </View>

          <Text style={styles.profileName}>{user?.name ?? "Zain Abbas Chaudhry"}</Text>
          <Text style={styles.profileRole}>{user?.department ?? "Executive"}</Text>

          <View style={styles.idRow}>
            <View style={styles.idChip}>
              <Ionicons name="id-card" size={14} color={C.GOLD} />
              <Text style={styles.idChipText}>ID: {user?.numericId ?? "EL-0001"}</Text>
            </View>
            <View style={styles.idChip}>
              <MaterialCommunityIcons name="link-variant" size={14} color={C.BLUE} />
              <Text style={styles.idChipText}>{user?.affiliateId ?? "EL-0001"}</Text>
            </View>
          </View>

          <View style={styles.statsStrip}>
            <View style={styles.stripItem}>
              <Text style={[styles.stripValue, { color: C.GOLD }]}>{formatPKR(user?.monthlySales ?? 0)}</Text>
              <Text style={styles.stripLabel}>This Month</Text>
            </View>
            <View style={styles.stripDivider} />
            <View style={styles.stripItem}>
              <Text style={[styles.stripValue, { color: C.SUCCESS }]}>{formatPKR(user?.totalSales ?? 0)}</Text>
              <Text style={styles.stripLabel}>Total Sales</Text>
            </View>
            <View style={styles.stripDivider} />
            <View style={styles.stripItem}>
              <Text style={[styles.stripValue, { color: C.BLUE }]}>{user?.rank ?? "Founder"}</Text>
              <Text style={styles.stripLabel}>Rank</Text>
            </View>
          </View>
        </LinearGradient>

        <View style={styles.content}>
          <Text style={styles.sectionTitle}>Account Info</Text>
          {[
            { icon: "mail", label: "Email", value: user?.email ?? "ceo@easylife.com.pk", color: C.BLUE },
            { icon: "call", label: "Phone", value: user?.phone ?? "+923440000000", color: C.SUCCESS },
            { icon: "calendar", label: "Joined", value: user?.joinDate ?? "Jan 2024", color: C.GOLD },
          ].map((item) => (
            <View key={item.label} style={styles.infoRow}>
              <View style={[styles.infoIcon, { backgroundColor: item.color + "22" }]}>
                <Ionicons name={item.icon as any} size={18} color={item.color} />
              </View>
              <View>
                <Text style={styles.infoLabel}>{item.label}</Text>
                <Text style={styles.infoValue}>{item.value}</Text>
              </View>
            </View>
          ))}

          <Text style={[styles.sectionTitle, { marginTop: 8 }]}>Actions</Text>
          {[
            {
              icon: "videocam",
              label: "Join Zoom Meeting",
              sub: "Connect with HODs for live training",
              color: BRAND.blue,
              onPress: openZoomMeeting,
            },
            {
              icon: "calendar",
              label: "Apply for Leave",
              sub: "Submit leave request for approval",
              color: C.GOLD,
              onPress: () => setModal("leave"),
            },
            {
              icon: "chatbox-ellipses",
              label: "File a Complaint",
              sub: "Report an issue or concern",
              color: "#FF9F43",
              onPress: () => setModal("complaint"),
            },
            {
              icon: "time",
              label: "Working Hours",
              sub: "Schedule your working hours",
              color: C.BLUE,
              onPress: () => Alert.alert("Coming Soon", "This feature will be available soon."),
            }
          ].map((action) => (
            <Pressable
              key={action.label}
              style={({ pressed }) => [styles.actionCard, { opacity: pressed ? 0.85 : 1 }]}
              onPress={() => {
                Haptics.selectionAsync();
                action.onPress();
              }}
            >
              <View style={[styles.actionIcon, { backgroundColor: action.color + "22" }]}>
                <Ionicons name={action.icon as any} size={22} color={action.color} />
              </View>
              <View style={{ flex: 1 }}>
                <Text style={styles.actionLabel}>{action.label}</Text>
                <Text style={styles.actionSub}>{action.sub}</Text>
              </View>
              <Ionicons name="chevron-forward" size={16} color={C.TEXT_SECONDARY} />
            </Pressable>
          ))}

          <Pressable
            style={({ pressed }) => [styles.logoutBtn, { opacity: pressed ? 0.85 : 1 }]}
            onPress={confirmLogout}
          >
            <Ionicons name="log-out-outline" size={20} color={C.ERROR} />
            <Text style={styles.logoutText}>Sign Out</Text>
          </Pressable>

          <Text style={styles.version}>Easylife v1.0 · Proud Pakistani Company (SMC-Pvt Ltd)</Text>
        </View>
      </ScrollView>

      <Modal visible={modal === "leave"} animationType="slide" transparent>
        <View style={styles.modalOverlay}>
          <View style={styles.modalSheet}>
            <View style={styles.modalHandle} />
            <View style={styles.modalHeader}>
              <Text style={styles.modalTitle}>Apply for Leave</Text>
              <Pressable onPress={() => setModal(null)}>
                <Ionicons name="close" size={24} color={C.TEXT} />
              </Pressable>
            </View>

            <ScrollView showsVerticalScrollIndicator={false} keyboardShouldPersistTaps="handled">
              <View style={styles.modalContent}>
                <Text style={styles.fieldLabel}>Leave Type</Text>
                <View style={styles.leaveTypes}>
                  {LEAVE_TYPES.map((t) => (
                    <Pressable
                      key={t}
                      style={[
                        styles.leaveTypeBtn,
                        leaveType === t && { backgroundColor: C.GOLD, borderColor: C.GOLD },
                      ]}
                      onPress={() => setLeaveType(t)}
                    >
                      <Text style={[styles.leaveTypeText, leaveType === t && { color: C.NAVY }]}>{t}</Text>
                    </Pressable>
                  ))}
                </View>

                <Text style={styles.fieldLabel}>Date(s)</Text>
                <TextInput
                  style={styles.textField}
                  placeholder="e.g. March 15 - March 16, 2025"
                  placeholderTextColor={C.TEXT_SECONDARY}
                  value={leaveDate}
                  onChangeText={setLeaveDate}
                />

                <Text style={styles.fieldLabel}>Reason</Text>
                <TextInput
                  style={[styles.textField, styles.textArea]}
                  placeholder="Describe your reason..."
                  placeholderTextColor={C.TEXT_SECONDARY}
                  value={leaveReason}
                  onChangeText={setLeaveReason}
                  multiline
                  numberOfLines={4}
                  textAlignVertical="top"
                />

                <Pressable
                  style={({ pressed }) => [styles.submitBtn, { opacity: pressed || leaveLoading ? 0.8 : 1 }]}
                  onPress={submitLeave}
                  disabled={leaveLoading}
                >
                  <LinearGradient
                    colors={[C.GOLD, C.GOLD_LIGHT]}
                    start={{ x: 0, y: 0 }}
                    end={{ x: 1, y: 0 }}
                    style={styles.submitGrad}
                  >
                    <Text style={styles.submitText}>Submit Leave Request</Text>
                  </LinearGradient>
                </Pressable>
              </View>
            </ScrollView>
          </View>
        </View>
      </Modal>

      <Modal visible={modal === "complaint"} animationType="slide" transparent>
        <View style={styles.modalOverlay}>
          <View style={styles.modalSheet}>
            <View style={styles.modalHandle} />
            <View style={styles.modalHeader}>
              <Text style={styles.modalTitle}>File a Complaint</Text>
              <Pressable onPress={() => setModal(null)}>
                <Ionicons name="close" size={24} color={C.TEXT} />
              </Pressable>
            </View>

            <View style={styles.modalContent}>
              <Text style={styles.fieldLabel}>Describe your complaint</Text>
              <TextInput
                style={[styles.textField, styles.textArea, { height: 140 }]}
                placeholder="Please provide details about your concern..."
                placeholderTextColor={C.TEXT_SECONDARY}
                value={complaint}
                onChangeText={setComplaint}
                multiline
                numberOfLines={6}
                textAlignVertical="top"
              />
              <View style={styles.infoNotice}>
                <Ionicons name="shield-checkmark" size={14} color={C.BLUE} />
                <Text style={styles.noticeText}>Your complaint is confidential and will be reviewed by management.</Text>
              </View>
              <Pressable
                style={({ pressed }) => [styles.submitBtn, { opacity: pressed || complaintLoading ? 0.8 : 1 }]}
                onPress={submitComplaint}
                disabled={complaintLoading}
              >
                <LinearGradient
                  colors={["#FF9F43", "#FFC371"]}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 0 }}
                  style={styles.submitGrad}
                >
                  <Text style={styles.submitText}>Submit Complaint</Text>
                </LinearGradient>
              </Pressable>
            </View>
          </View>
        </View>
      </Modal>
    </View>
  );
}

